import inovxJson from '../tracks/inovx.json';
import tt1Json from '../tracks/tt1.json';
import type { TrackModel } from './model';
import { buildTrack } from './model';
import { parseTrackJson } from './schema';

/** Built-in tracks (generated by `pnpm trackgen` from tools/harness/src/layouts.ts). */
export const BUILTIN_TRACKS = {
  tt1: tt1Json as unknown,
  inovx: inovxJson as unknown,
} as const;

export type BuiltinTrackId = keyof typeof BUILTIN_TRACKS;

export const BUILTIN_TRACK_LIST: { id: BuiltinTrackId; name: string }[] = [
  { id: 'tt1', name: 'TT-1 Test Track' },
  { id: 'inovx', name: 'INOVX International Circuit' },
];

const cache = new Map<string, TrackModel>();

export function loadBuiltinTrack(id: BuiltinTrackId): TrackModel {
  let t = cache.get(id);
  if (!t) {
    t = buildTrack(parseTrackJson(BUILTIN_TRACKS[id]));
    cache.set(id, t);
  }
  return t;
}
